query GetProductsByCateId{
    products(
            filter: {
                static: {
                    categories: ["30"],
                    province_id: 30,
                    stock: {
                       from: 1
                    },
                   company_stock_id: [46, 4920],

                   promotion_percent: { from: 20 }



                },
                dynamic: {


                }
            },
            page: 1,
            size: 20,
            sort: [{view: desc}],
        )
    {
        general{
            product_id
            name

            sku
            doc_quyen
            manufacturer
            url_key
            url_path
            categories{
                categoryId
                name
                uri
            }
            review{
                total_count
                average_rating
            }
        },
        filterable {
            name
            is_installment
            stock_available_id
            company_stock_id
            filter {
               id
               Label
            }
            is_parent
            price
            prices

            special_price
            display_root_price
            display_price
            promotion_information
            promotion_percent
            thumbnail
            promotion_pack
            sticker
            flash_sale_types
            is_new_arrival
            child_product
            is_dropshipping
            allow_cart_types
            default {
              product_id
            }
            default_bundle_discount {
              pricing_summaries
            }
            promotion_info
            delivery_badge
        },
    }
}
